    content: "const fs = require('fs');\nconst file = 'apps/web-ele/src/views/finance/assets/manage/change-voucher/index.vue';\nlet s = fs.readFileSync(file, 'utf8');\ns = s.replace('label=\"变动期间\"', 'label=\"变动时间\"');\nfs.writeFileSync(file, s);\nconsole.log('updated column label: 变动期间 -> 变动时间');\n",
