    path: "tmp_patch_aux_skill_route_module.cjs",
    content: "const fs=require('fs');\nfor(const f of ['apps/web-ele/skills/finance/cwhs/auxiliary-project-balance.md','apps/web-ele/skills/finance/cwhs/auxiliary-project-detail.md']){\n  let s=fs.readFileSync(f,'utf8');\n  s=s.replaceAll('src/router/routes/modules/erp-finance-voucher.ts','src/router/routes/modules/erp-finance-chronological-ledger.ts');\n  fs.writeFileSync(f,s);\n}\nconsole.log('patched skill route module');",
