    content: "const fs=require('fs');\nconst p='apps/web-ele/src/views/finance/settings/auxiliary/index.vue';\nlet s=fs.readFileSync(p,'utf8');\nconst anchor=`.aux-filter-toolbar {\n  border-bottom: 1px solid var(--el-border-color-light);\n  background: var(--el-bg-color);\n  padding: 12px;\n}\n`;\nconst insert=`.aux-filter-toolbar {\n  border-bottom: 1px solid var(--el-border-color-light);\n  background: var(--el-bg-color);\n  padding: 12px;\n}\n\n.aux-filter-toolbar :deep(.el-button) {\n  height: 28px;\n  min-height: 28px;\n  padding: 5px 11px;\n  font-size: 12px;\n  line-height: 1;\n  white-space: nowrap;\n}\n\n.aux-filter-toolbar :deep(.el-button.is-text) {\n  padding-right: 8px;\n  padding-left: 8px;\n}\n\n.aux-filter-toolbar :deep(.el-button span) {\n  white-space: nowrap;\n}\n`;\nif(!s.includes('.aux-filter-toolbar :deep(.el-button)')){\n  s=s.replace(anchor,insert);\n}\nfs.writeFileSync(p,s);\nconsole.log('toolbar buttons unified small');\n",
