    content: "const fs=require('fs');\nconst p='apps/web-ele/src/views/finance/settings/auxiliary/index.vue';\nlet s=fs.readFileSync(p,'utf8');\n\nconst old=`          <div v-if=\"filterCollapsed\" class=\"aux-filter-compact\">\n            <ElInput\n              v-model=\"keyword\"\n              class=\"aux-filter-compact__input\"\n              placeholder=\"输入编码或名称\"\n              clearable\n              @keyup.enter=\"handleQuery\"\n            />\n            <div class=\"aux-filter-compact__actions\">\n              <ElButton type=\"primary\" @click=\"handleQuery\">查询</ElButton>\n              <ElButton @click=\"handlePrint\">打印</ElButton>\n              <ElButton @click=\"handleExport\">导出</ElButton>\n            </div>\n            <div\n              v-if=\"filterSummary\"\n              class=\"aux-filter-summary\"\n              :title=\"filterSummary\"\n            >\n              {{ filterSummary }}\n            </div>\n            <ElButton class=\"aux-filter-expand\" text type=\"primary\" @click=\"filterCollapsed = false\">\n              展开筛选\n            </ElButton>\n          </div>`;\nconst neu=`          <div v-if=\"filterCollapsed\" class=\"aux-filter-compact\">\n            <div class=\"aux-filter-compact__left\">\n              <ElInput\n                v-model=\"keyword\"\n                class=\"aux-filter-compact__input\"\n                placeholder=\"输入编码或名称\"\n                clearable\n                @keyup.enter=\"handleQuery\"\n              />\n              <div\n                v-if=\"filterSummary\"\n                class=\"aux-filter-summary\"\n                :title=\"filterSummary\"\n              >\n                {{ filterSummary }}\n              </div>\n            </div>\n            <div class=\"aux-filter-compact__actions\">\n              <ElButton type=\"primary\" @click=\"handleQuery\">查询</ElButton>\n              <ElButton @click=\"handlePrint\">打印</ElButton>\n              <ElButton @click=\"handleExport\">导出</ElButton>\n              <ElButton class=\"aux-filter-expand\" text type=\"primary\" @click=\"filterCollapsed = false\">\n                展开筛选\n              </ElButton>\n            </div>\n          </div>`;\nif(!s.includes('aux-filter-compact__left')) s=s.replace(old,neu);\n\ns=s.replace(`.aux-filter-compact {\n  display: flex;\n  align-items: center;\n  justify-content: flex-start;\n  gap: 8px;\n  min-width: 0;\n}`, `.aux-filter-compact {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  min-width: 0;\n}\n\n.aux-filter-compact__left {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n}`);\n\ns=s.replace(`@media (max-width: 640px) {\n  .aux-filter-grid,\n  .aux-filter-actions,\n  .aux-filter-buttons {\n    display: grid;\n    grid-template-columns: 1fr;\n  }\n\n  .aux-filter-compact {\n    display: flex;\n    flex-wrap: wrap;\n  }\n\n  .aux-filter-compact__input {\n    width: 100%;\n    flex: 1 1 100%;\n  }\n\n  .aux-filter-summary {\n    max-width: none;\n    flex: 1 1 100%;\n    order: 3;\n  }\n\n  .aux-filter-expand {\n    margin-left: auto;\n  }\n\n  .aux-filter-buttons {\n    justify-content: stretch;\n  }\n}`, `@media (max-width: 640px) {\n  .aux-filter-grid,\n  .aux-filter-actions,\n  .aux-filter-buttons,\n  .aux-filter-compact,\n  .aux-filter-compact__left {\n    display: grid;\n    grid-template-columns: 1fr;\n  }\n\n  .aux-filter-compact__input {\n    width: 100%;\n    flex: 1 1 100%;\n  }\n\n  .aux-filter-compact__actions {\n    display: grid;\n    grid-template-columns: repeat(4, max-content);\n    justify-content: start;\n  }\n\n  .aux-filter-summary {\n    max-width: none;\n    flex: 1 1 100%;\n  }\n\n  .aux-filter-buttons {\n    justify-content: stretch;\n  }\n}`);\n\nfs.writeFileSync(p,s);\nconsole.log('compact toolbar row patched');\n",
