    path: "tmp_patch_inexpcate_form_vertical.cjs",
    content: "const fs = require('fs');\nconst file = 'apps/web-ele/src/views/finance/funds/inexpcate/modules/form.vue';\nlet s = fs.readFileSync(file, 'utf8');\ns = s.replace('<ElForm class=\"inexp-cate-form\" label-position=\"right\" label-width=\"150px\">', '<ElForm class=\"inexp-cate-form\" label-position=\"top\">');\ns = s.replace(/<style scoped>[\\s\\S]*?<\\/style>/, `<style scoped>\n.inexp-cate-form {\n  width: 480px;\n  max-width: calc(100vw - 72px);\n  padding: 8px 16px 12px;\n}\n\n.inexp-cate-form :deep(.el-form-item) {\n  margin-bottom: 16px;\n}\n\n.inexp-cate-form :deep(.el-form-item__label) {\n  padding-bottom: 6px;\n  line-height: 20px;\n  font-weight: 500;\n}\n\n.inexp-cate-form :deep(.el-input),\n.inexp-cate-form :deep(.el-select),\n.inexp-cate-form :deep(.el-textarea) {\n  width: 100%;\n}\n\n.inexp-form-help {\n  margin-top: -2px;\n  color: var(--el-text-color-secondary);\n  font-size: 13px;\n  line-height: 22px;\n}\n\n.inexp-form-help__mark {\n  display: inline-flex;\n  width: 14px;\n  height: 14px;\n  align-items: center;\n  justify-content: center;\n  border-radius: 50%;\n  background: var(--el-color-warning);\n  color: #fff;\n  font-size: 12px;\n  line-height: 14px;\n}\n\n.inexp-form-help__line {\n  padding-left: 20px;\n}\n</style>`);\nfs.writeFileSync(file, s);\n",
