    content: "const fs = require('fs');\nconst file = 'apps/web-ele/src/views/finance/funds/reconcile/index.vue';\nlet s = fs.readFileSync(file, 'utf8');\n\nfunction replaceOnce(from, to) {\n  if (!s.includes(from)) throw new Error('not found: ' + from.slice(0, 120));\n  s = s.replace(from, to);\n}\n\nreplaceOnce(\n  \"import { computed, onMounted, reactive, ref, watch } from 'vue';\",\n  \"import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';\",\n);\n\nreplaceOnce(\n  \"  ElCheckbox,\\n  ElDatePicker,\",\n  \"  ElCheckbox,\\n  ElDatePicker,\\n  ElIcon,\",\n);\n\nreplaceOnce(\n  \"} from 'element-plus';\\n\",\n  \"} from 'element-plus';\\nimport { ArrowDown, ArrowUp } from '@element-plus/icons-vue';\\n\",\n);\n\nreplaceOnce(\n  \"const printLoading = ref(false);\\nconst keyword = ref('');\\nconst printFrameRef\",\n  \"const printLoading = ref(false);\\nconst keyword = ref('');\\nconst filterCollapsed = ref(false);\\nconst isSmallScreen = ref(false);\\nconst printFrameRef\",\n);\n\nreplaceOnce(\n  \"function initMonth() {\\n  const now = new Date();\\n  query.month = `${now.getFullYear()}-${pad2(now.getMonth() + 1)}`;\\n}\\n\",\n  \"function initMonth() {\\n  const now = new Date();\\n  query.month = `${now.getFullYear()}-${pad2(now.getMonth() + 1)}`;\\n}\\n\\nfunction syncSmallScreen() {\\n  if (typeof window === 'undefined') return;\\n  const next = window.innerWidth <= 1440;\\n  const changed = next !== isSmallScreen.value;\\n  isSmallScreen.value = next;\\n  if (changed || next) filterCollapsed.value = next;\\n}\\n\\nfunction toggleFilters() {\\n  filterCollapsed.value = !filterCollapsed.value;\\n}\\n\",\n);\n\nreplaceOnce(\n  \"onMounted(async () => {\\n  initMonth();\\n  await reload();\\n});\",\n  \"onMounted(async () => {\\n  initMonth();\\n  syncSmallScreen();\\n  window.addEventListener('resize', syncSmallScreen);\\n  await reload();\\n});\\n\\nonBeforeUnmount(() => {\\n  window.removeEventListener('resize', syncSmallScreen);\\n});\",\n);\n\nreplaceOnce(\n  \"        <div class=\\\"screen-toolbar\\\">\\n        <div class=\\\"table-toolbar__filters\\\">\",\n  \"        <div class=\\\"screen-toolbar\\\" :class=\\\"{ 'is-collapsed': filterCollapsed }\\\">\\n          <div class=\\\"screen-toolbar__summary\\\">\\n            <div class=\\\"summary-text\\\">\\n              <span>查询月份：{{ query.month || '-' }}</span>\\n              <span>资金类型：{{ query.fundsKind }}</span>\\n              <span>资金账户：{{ accountLabel }}</span>\\n              <span v-if=\\\"keywordText\\\">搜索：{{ keyword }}</span>\\n            </div>\\n            <ElButton class=\\\"collapse-button\\\" text @click=\\\"toggleFilters\\\">\\n              {{ filterCollapsed ? '展开筛选' : '收起筛选' }}\\n              <ElIcon class=\\\"collapse-icon\\\">\\n                <ArrowDown v-if=\\\"filterCollapsed\\\" />\\n                <ArrowUp v-else />\\n              </ElIcon>\\n            </ElButton>\\n          </div>\\n\\n        <div v-show=\\\"!filterCollapsed\\\" class=\\\"table-toolbar__filters\\\">\",\n);\n\nreplaceOnce(\n  \"        <div class=\\\"table-toolbar__actions\\\">\\n          <ElButton type=\\\"primary\\\" :loading=\\\"loading\\\" @click=\\\"reload\\\">查询</ElButton>\\n          <ElButton :loading=\\\"printLoading\\\" @click=\\\"onPrint\\\">打印</ElButton>\\n          <ElButton type=\\\"primary\\\" @click=\\\"onExportJson\\\">导出</ElButton>\\n        </div>\",\n  \"        <div v-show=\\\"!filterCollapsed\\\" class=\\\"table-toolbar__actions\\\">\\n          <ElButton type=\\\"primary\\\" :loading=\\\"loading\\\" @click=\\\"reload\\\">查询</ElButton>\\n          <ElButton :loading=\\\"printLoading\\\" @click=\\\"onPrint\\\">打印</ElButton>\\n          <ElButton type=\\\"primary\\\" @click=\\\"onExportJson\\\">导出</ElButton>\\n        </div>\",\n);\n\nreplaceOnce(\n`.screen-toolbar {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 12px;\n  border-bottom: 1px solid var(--el-border-color-light);\n  background: var(--el-fill-color-blank);\n  flex-wrap: wrap;\n}`,\n`.screen-toolbar {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 12px;\n  border-bottom: 1px solid var(--el-border-color-light);\n  background: var(--el-fill-color-blank);\n  flex-wrap: wrap;\n}\n\n.screen-toolbar__summary {\n  display: none;\n  width: 100%;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.summary-text {\n  display: flex;\n  min-width: 0;\n  flex: 1;\n  flex-wrap: wrap;\n  gap: 8px 16px;\n  color: var(--el-text-color-secondary);\n  font-size: 13px;\n}\n\n.collapse-button {\n  flex: 0 0 auto;\n}\n\n.collapse-icon {\n  margin-left: 4px;\n}`,\n);\n\nreplaceOnce(\n`@media (max-width: 1440px) {\n  .screen-toolbar {\n    align-items: stretch;\n  }\n\n  .table-toolbar__filters {`,\n`@media (max-width: 1440px) {\n  .screen-toolbar {\n    align-items: stretch;\n  }\n\n  .screen-toolbar__summary {\n    display: flex;\n  }\n\n  .screen-toolbar.is-collapsed {\n    padding-top: 10px;\n    padding-bottom: 10px;\n  }\n\n  .table-toolbar__filters {`,\n);\n\nfs.writeFileSync(file, s);\nconsole.log('patched collapsible filters');\n",
