    path: "tmp_patch_subject_balance_search_width.cjs",
    content: "const fs = require('fs');\nconst p = 'apps/web-ele/src/views/finance/ledger/subject-balance/index.vue';\nlet s = fs.readFileSync(p, 'utf8');\nconst before = `.filter-item--search {\n  flex: 1;\n  min-width: 260px;\n}`;\nconst after = `.filter-item--search {\n  flex: 0 0 auto;\n}`;\nif (!s.includes(before)) {\n  throw new Error('未找到科目搜索筛选项样式，请检查页面结构是否已变化');\n}\ns = s.replace(before, after);\nconst beforeInput = `.search-box__input {\n  flex: 1;\n}`;\nconst afterInput = `.search-box__input {\n  width: 260px;\n  flex: 0 0 auto;\n}`;\nif (!s.includes(beforeInput)) {\n  throw new Error('未找到科目搜索输入框样式，请检查页面结构是否已变化');\n}\ns = s.replace(beforeInput, afterInput);\nfs.writeFileSync(p, s, 'utf8');\n",
