function listPatches() {
  return PATCH_SOURCES.map((item, index) => ({ index: index + 1, path: item.path, bytes: Buffer.byteLength(item.content, 'utf8') }));
}

function extractPatches(targetDir = 'tmp_patch_extracted') {
  const fs = require('fs');
  const path = require('path');
  for (const item of PATCH_SOURCES) {
    const file = path.join(targetDir, item.path);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, item.content, 'utf8');
  }
  return PATCH_SOURCES.length;
}

if (require.main === module) {
  const cmd = process.argv[2] || 'list';
  if (cmd === 'extract') {
    const count = extractPatches(process.argv[3] || 'tmp_patch_extracted');
    console.log(`extracted ${count} patch scripts`);
  } else {
    console.log(JSON.stringify({ count: PATCH_SOURCES.length, patches: listPatches() }, null, 2));
  }
}

module.exports = { PATCH_SOURCES, listPatches, extractPatches };
